/* ────────────────────────────────────────────────────────────
   LOGO OFICIAL LEVEN
   Máscaras PNG extraídas del archivo original (Logos_leven_1.png).
   Se colorean por CSS mask, por eso funcionan en verde y en blanco
   sin perder el trazo original del isotipo ni de la tipografía.
──────────────────────────────────────────────────────────── */
const MASK_ISO = "data:image/png;base64,";
const MASK_WORD = "data:image/png;base64,";
const MASK_TAG = "data:image/png;base64,";
const R_ISO = 1, R_WORD = 3.3854, R_TAG = 11.0227;

const MaskImg = ({ src, h, ratio, color, title }) => (
  <span role="img" aria-label={title} style={{
    display: "block", height: h, width: h * ratio, backgroundColor: color,
    WebkitMaskImage: `url("${src}")`, maskImage: `url("${src}")`,
    WebkitMaskSize: "contain", maskSize: "contain",
    WebkitMaskRepeat: "no-repeat", maskRepeat: "no-repeat",
    WebkitMaskPosition: "center", maskPosition: "center", flexShrink: 0,
  }} />
);

/* Solo el isotipo */
const LevenMark = ({ size = 34, color = C.deep }) => (
  <MaskImg src={MASK_ISO} h={size} ratio={R_ISO} color={color} title="Leven" />
);

/* Lockup horizontal: isotipo + "Leven" sobre "Negocios inmobiliarios", ambos alineados a la izquierda */
const LevenLogo = ({ color = C.deep, sub = true, size = 34 }) => (
  <div className="flex items-center" style={{ gap: size * 0.34 }}>
    <MaskImg src={MASK_ISO} h={size} ratio={R_ISO} color={color} title="Leven" />
    <span className="flex flex-col items-start" style={{ gap: size * 0.16 }}>
      <MaskImg src={MASK_WORD} h={size * 0.46} ratio={R_WORD} color={color} title="Leven" />
      {sub && <MaskImg src={MASK_TAG} h={size * 0.135} ratio={R_TAG} color={color} title="Negocios inmobiliarios" />}
    </span>
  </div>
);

