const Store = createContext(null);
const useStore = () => useContext(Store);
const uid = (p) => `${p}${Date.now()}${Math.floor(Math.random() * 900 + 100)}`;

const StoreProvider = ({ children }) => {
  const [agents, setAgents] = useState(SEED_AGENTS);
  const [properties, setProperties] = useState(SEED_PROPERTIES);
  const [contacts, setContacts] = useState(SEED_CONTACTS);
  const [tasks, setTasks] = useState(SEED_TASKS);
  const [campaigns, setCampaigns] = useState(SEED_CAMPAIGNS);
  const [content, setContent] = useState(SEED_CONTENT);
  const [captaciones, setCaptaciones] = useState(SEED_CAPTACIONES);
  const [settings, setSettings] = useState(SEED_SETTINGS);
  const [toast, setToast] = useState(null);

  const notify = (msg) => {
    setToast(msg);
    setTimeout(() => setToast(null), 2600);
  };

  const nextCode = () => {
    const nums = properties.map((p) => parseInt(p.codigo.split("-")[1], 10)).filter(Boolean);
    return `LV-${Math.max(1041, ...nums) + 1}`;
  };

  const api = {
    agents, properties, contacts, tasks, campaigns, content, captaciones, settings, notify, toast,
    agentName: (id) => agents.find((a) => a.id === id)?.nombre ?? "—",
    propCode: (id) => properties.find((p) => p.id === id)?.codigo ?? "—",

    addProperty: (d) => {
      const p = {
        ...d, id: uid("p"), codigo: nextCode(), destacada: false, visitas: 0, consultas: 0,
        publicada: new Date().toISOString().slice(0, 10),
        caracteristicas: d.caracteristicas ? String(d.caracteristicas).split(",").map((s) => s.trim()).filter(Boolean) : [],
        servicios: d.servicios ? String(d.servicios).split(",").map((s) => s.trim()).filter(Boolean) : [],
        img: d.imagen ? [d.imagen] : [IMG("photo-1512917774080-9991f1c4c750")],
      };
      setProperties((x) => [p, ...x]);
      notify(`Propiedad ${p.codigo} creada`);
    },
    updateProperty: (id, d) => { setProperties((x) => x.map((p) => (p.id === id ? { ...p, ...d } : p))); notify("Propiedad actualizada"); },
    removeProperty: (id) => { setProperties((x) => x.filter((p) => p.id !== id)); notify("Propiedad eliminada"); },

    addContact: (d) => { setContacts((x) => [{ ...d, id: uid("c") }, ...x]); notify("Contacto creado"); },
    updateContact: (id, d) => { setContacts((x) => x.map((c) => (c.id === id ? { ...c, ...d } : c))); notify("Contacto actualizado"); },
    removeContact: (id) => { setContacts((x) => x.filter((c) => c.id !== id)); notify("Contacto eliminado"); },
    moveContact: (id, estado) => setContacts((x) => x.map((c) => (c.id === id ? { ...c, estado } : c))),

    addTask: (d) => { setTasks((x) => [{ ...d, id: uid("t") }, ...x]); notify("Tarea creada"); },
    updateTask: (id, d) => { setTasks((x) => x.map((t) => (t.id === id ? { ...t, ...d } : t))); notify("Tarea actualizada"); },
    removeTask: (id) => { setTasks((x) => x.filter((t) => t.id !== id)); notify("Tarea eliminada"); },
    toggleTask: (id) => setTasks((x) => x.map((t) => (t.id === id ? { ...t, estado: t.estado === "Completada" ? "Pendiente" : "Completada" } : t))),

    addCampaign: (d) => { setCampaigns((x) => [{ ...d, id: uid("cp") }, ...x]); notify("Campaña creada"); },
    updateCampaign: (id, d) => { setCampaigns((x) => x.map((c) => (c.id === id ? { ...c, ...d } : c))); notify("Campaña actualizada"); },
    removeCampaign: (id) => { setCampaigns((x) => x.filter((c) => c.id !== id)); notify("Campaña eliminada"); },

    addContent: (d) => { setContent((x) => [{ ...d, id: uid("k") }, ...x]); notify("Contenido creado"); },
    updateContent: (id, d) => setContent((x) => x.map((k) => (k.id === id ? { ...k, ...d } : k))),
    removeContent: (id) => { setContent((x) => x.filter((k) => k.id !== id)); notify("Contenido eliminado"); },

    addCaptacion: (d) => setCaptaciones((x) => [{ ...d, id: uid("s"), fecha: new Date().toISOString().slice(0, 10), estado: "Nueva" }, ...x]),
    updateCaptacion: (id, d) => { setCaptaciones((x) => x.map((c) => (c.id === id ? { ...c, ...d } : c))); notify("Solicitud actualizada"); },

    addAgent: (d) => { setAgents((x) => [...x, { ...d, id: uid("a"), ops: 0, consultas: 0, activo: true }]); notify("Agente agregado"); },
    updateAgent: (id, d) => { setAgents((x) => x.map((a) => (a.id === id ? { ...a, ...d } : a))); notify("Agente actualizado"); },
    removeAgent: (id) => { setAgents((x) => x.filter((a) => a.id !== id)); notify("Agente eliminado"); },

    saveSettings: (d) => { setSettings((s) => ({ ...s, ...d })); notify("Configuración guardada"); },
    toggleIntegracion: (k) => setSettings((s) => ({ ...s, integraciones: { ...s.integraciones, [k]: !s.integraciones[k] } })),
  };

  return <Store.Provider value={api}>{children}</Store.Provider>;
};

