const money = (v, m) => (m === "USD" ? `USD ${Number(v).toLocaleString("es-AR")}` : `$ ${Number(v).toLocaleString("es-AR")}`);

const Reveal = ({ children, delay = 0, className = "" }) => {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => e.isIntersecting && setInView(true), { threshold: 0.12 });
    io.observe(el);
    return () => io.disconnect();
  }, []);
  return <div ref={ref} className={`lv-reveal ${inView ? "in" : ""} ${className}`} style={{ transitionDelay: `${delay}ms` }}>{children}</div>;
};

const SmartImg = ({ src, className = "", style = {} }) => {
  const [err, setErr] = useState(false);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => { setErr(false); setLoaded(false); }, [src]);

  const Placeholder = (
    <div className={className} style={{ ...style, background: `linear-gradient(135deg, ${C.deep}, ${C.deepSoft})` }}>
      <div className="w-full h-full flex items-center justify-center">
        <LevenMark size={44} color="rgba(255,255,255,.32)" />
      </div>
    </div>
  );

  if (err || !src) return Placeholder;

  return (
    <>
      {!loaded && Placeholder}
      <img src={src} alt="" aria-hidden="true" className={className}
           style={{ ...style, display: loaded ? undefined : "none" }}
           onLoad={() => setLoaded(true)} onError={() => setErr(true)} loading="lazy" />
    </>
  );
};

