const CatalogPage = ({ filtro }) => {
  const { go } = useNav();
  const { properties } = useStore();
  const [op, setOp] = useState(filtro?.operacion ?? "Todas");
  const [tipo, setTipo] = useState(filtro?.tipo ?? "Todos");
  const [barrio, setBarrio] = useState(filtro?.barrio ?? "Todos");
  const [q, setQ] = useState("");
  const [orden, setOrden] = useState("Recientes");
  const barrios = useMemo(() => ["Todos", ...new Set(properties.map((p) => p.barrio))], [properties]);
  const tipos = useMemo(() => ["Todos", ...new Set(properties.map((p) => p.tipo))], [properties]);

  const list = useMemo(() => {
    let r = properties.filter((p) => !["Borrador", "Pendiente de aprobación", "Finalizada"].includes(p.estado));
    if (op !== "Todas") r = r.filter((p) => p.operacion === op);
    if (tipo !== "Todos") r = r.filter((p) => p.tipo === tipo);
    if (barrio !== "Todos") r = r.filter((p) => p.barrio === barrio);
    if (q.trim()) { const s = q.toLowerCase(); r = r.filter((p) => (p.titulo + p.barrio + p.codigo + p.direccion).toLowerCase().includes(s)); }
    if (orden === "Menor precio") r = [...r].sort((a, b) => a.precio - b.precio);
    if (orden === "Mayor precio") r = [...r].sort((a, b) => b.precio - a.precio);
    if (orden === "Recientes") r = [...r].sort((a, b) => b.publicada.localeCompare(a.publicada));
    return r;
  }, [properties, op, tipo, barrio, q, orden]);

  return (
    <div className="pt-32 pb-24 max-w-7xl mx-auto px-5 sm:px-8">
      <Reveal>
        <div className="text-xs tracking-[.24em] uppercase mb-3" style={{ color: C.accent, fontFamily: FONT_BODY }}>Catálogo</div>
        <h1 style={{ fontFamily: FONT_HEAD, fontWeight: 300, color: C.ink, fontSize: "clamp(2rem,4.5vw,3.4rem)", letterSpacing: "-0.03em" }}>Propiedades disponibles</h1>
      </Reveal>

      <Reveal delay={100}>
        <div className="mt-10 p-5 rounded-sm grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4" style={{ background: C.sandLight, border: `1px solid ${C.line}` }}>
          <div className="lg:col-span-2">
            <label className="block text-xs mb-2" style={{ color: C.muted, fontFamily: FONT_BODY }}>Buscar</label>
            <div className="relative">
              <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2" style={{ color: C.muted }} />
              <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Código, barrio o dirección"
                     className="w-full pl-9 pr-3 py-3 text-sm rounded-sm border bg-white" style={inputStyle} />
            </div>
          </div>
          {[["Operación", op, setOp, ["Todas", "Venta", "Alquiler"]], ["Tipo", tipo, setTipo, tipos], ["Barrio", barrio, setBarrio, barrios]].map(([label, val, set, opts]) => (
            <div key={label}>
              <label className="block text-xs mb-2" style={{ color: C.muted, fontFamily: FONT_BODY }}>{label}</label>
              <select value={val} onChange={(e) => set(e.target.value)} className="w-full py-3 px-3 text-sm rounded-sm border bg-white" style={inputStyle}>
                {opts.map((o) => <option key={o}>{o}</option>)}
              </select>
            </div>
          ))}
        </div>
      </Reveal>

      <div className="flex items-center justify-between mt-8 mb-8">
        <div className="text-sm" style={{ color: C.muted, fontFamily: FONT_BODY }}>{list.length} {list.length === 1 ? "propiedad" : "propiedades"}</div>
        <select value={orden} onChange={(e) => setOrden(e.target.value)} className="text-sm py-2 px-3 rounded-sm border bg-white" style={inputStyle}>
          {["Recientes", "Menor precio", "Mayor precio"].map((o) => <option key={o}>{o}</option>)}
        </select>
      </div>

      {list.length === 0 ? (
        <div className="py-24 text-center" style={{ color: C.muted, fontFamily: FONT_BODY }}>
          <Filter size={30} className="mx-auto mb-4 opacity-40" />No hay propiedades que coincidan con los filtros.
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8 sm:gap-10">
          {list.map((p, i) => (
            <Reveal key={p.id} delay={(i % 3) * 90}>
              <PropertyCard p={p} onClick={() => go("public", "propiedad", { id: p.id })} />
            </Reveal>
          ))}
        </div>
      )}
    </div>
  );
};

const ConsultForm = ({ propiedad, compact }) => {
  const { addContact, properties } = useStore();
  const [sent, setSent] = useState(false);
  const [f, setF] = useState({ nombre: "", tel: "", email: "", msg: "" });
  const [err, setErr] = useState({});

  const submit = () => {
    const e = {};
    if (!f.nombre.trim()) e.nombre = "Requerido";
    if (!f.tel.trim()) e.tel = "Requerido";
    if (!/^\S+@\S+\.\S+$/.test(f.email)) e.email = "Email inválido";
    setErr(e);
    if (Object.keys(e).length) return;
    const [nombre, ...rest] = f.nombre.trim().split(" ");
    addContact({
      nombre, apellido: rest.join(" ") || "—", tel: f.tel, email: f.email, origen: "Web",
      propiedad: propiedad?.id ?? "", busca: propiedad?.operacion ?? "Venta", presupuesto: "—",
      zona: propiedad?.barrio ?? "—", agente: propiedad?.agente ?? (properties[0]?.agente ?? "a1"),
      estado: "Nuevo", prioridad: "Media", proxima: "Primer contacto",
      fecha: new Date().toISOString().slice(0, 10), notas: f.msg,
    });
    setSent(true);
  };

  if (sent)
    return (
      <div className="p-7 rounded-sm text-center" style={{ background: C.sandLight, border: `1px solid ${C.line}` }}>
        <CheckCircle2 size={30} className="mx-auto mb-4" style={{ color: C.deep }} />
        <div style={{ fontFamily: FONT_HEAD, fontWeight: 500, color: C.ink }}>Consulta enviada</div>
        <p className="text-sm mt-2" style={{ color: C.muted, fontFamily: FONT_BODY }}>
          Ingresó al CRM del panel. Un asesor te va a contactar a la brevedad.
        </p>
      </div>
    );

  return (
    <div className={compact ? "" : "p-7 rounded-sm"} style={compact ? {} : { background: "#fff", border: `1px solid ${C.line}` }}>
      {!compact && <div className="mb-5" style={{ fontFamily: FONT_HEAD, fontWeight: 500, color: C.ink }}>Consultar por esta propiedad</div>}
      <div className="space-y-4">
        {[["Nombre y apellido", "nombre"], ["Teléfono", "tel"], ["Email", "email"]].map(([label, key]) => (
          <Field key={key} label={label} error={err[key]}>
            <input value={f[key]} onChange={(e) => setF({ ...f, [key]: e.target.value })} className={inputCls}
                   style={{ ...inputStyle, borderColor: err[key] ? "#dc2626" : C.line }} />
          </Field>
        ))}
        <Field label="Mensaje">
          <textarea rows={3} value={f.msg} onChange={(e) => setF({ ...f, msg: e.target.value })}
                    placeholder={`Hola, me interesa ${propiedad?.codigo ?? "una propiedad"}.`} className={inputCls} style={inputStyle} />
        </Field>
        <button onClick={submit} className="w-full py-3.5 rounded-sm text-sm transition-opacity hover:opacity-90"
                style={{ background: C.accent, color: "#fff", fontFamily: FONT_BODY }}>Enviar consulta</button>
      </div>
    </div>
  );
};

