/* ── Modal central "Nuevo" (usado por el topbar en todas las secciones) ── */
const QuickCreate = ({ open, onClose, initialKind }) => {
  const s = useStore();
  const [kind, setKind] = useState(initialKind ?? "propiedad");
  useEffect(() => { if (open) setKind(initialKind ?? "propiedad"); }, [open, initialKind]);

  const cfg = {
    propiedad: { title: "Nueva propiedad", fields: propertyFields(s.agents), initial: { operacion: "Venta", tipo: "Departamento", moneda: "USD", estado: "Borrador", agente: s.agents[0]?.id, localidad: "Córdoba", provincia: "Córdoba" }, submit: s.addProperty },
    contacto: { title: "Nuevo contacto", fields: contactFields(s.agents, s.properties), initial: { origen: "Web", busca: "Venta", estado: "Nuevo", prioridad: "Media", agente: s.agents[0]?.id, fecha: new Date().toISOString().slice(0, 10) }, submit: s.addContact },
    tarea: { title: "Nueva tarea", fields: taskFields(s.agents, s.properties), initial: { tipo: "Llamada", estado: "Pendiente", agente: s.agents[0]?.id, fecha: new Date().toISOString().slice(0, 10), hora: "10:00" }, submit: s.addTask },
    campana: { title: "Nueva campaña", fields: campaignFields(s.properties), initial: { plataforma: "Meta Ads", estado: "Activa", inicio: new Date().toISOString().slice(0, 10), consultas: 0, ops: 0 }, submit: s.addCampaign },
    contenido: { title: "Nuevo contenido", fields: contentFields(s.properties), initial: { formato: "Post", red: "Instagram", estado: "Borrador", fecha: new Date().toISOString().slice(0, 10) }, submit: (d) => s.addContent({ ...d, media: null }) },
    agente: { title: "Nuevo usuario / agente", fields: agentFields, initial: { rol: "Agente" }, submit: s.addAgent },
  }[kind];

  if (!open) return null;

  return (
    <Modal open={open} onClose={onClose} title="Crear nuevo registro" subtitle="Elegí qué querés cargar" wide>
      <div className="flex flex-wrap gap-2 mb-7">
        {[["propiedad", "Propiedad", Building2], ["contacto", "Contacto", Users], ["tarea", "Tarea", CalendarDays],
          ["campana", "Campaña", Megaphone], ["contenido", "Contenido", Sparkles], ["agente", "Usuario", Settings]].map(([k, label, Icon]) => (
          <button key={k} onClick={() => setKind(k)} className="flex items-center gap-2 px-4 py-2.5 rounded-sm text-sm transition-colors"
                  style={{ background: kind === k ? C.deep : "#fff", color: kind === k ? "#fff" : C.muted, border: `1px solid ${kind === k ? C.deep : C.line}`, fontFamily: FONT_BODY }}>
            <Icon size={14} /> {label}
          </button>
        ))}
      </div>
      <InlineForm key={kind} fields={cfg.fields} initial={cfg.initial} submitLabel={cfg.title} onSubmit={(d) => { cfg.submit(d); onClose(); }} onCancel={onClose} />
    </Modal>
  );
};

/* Formulario inline reutilizable (mismo motor que FormModal, sin modal) */
const InlineForm = ({ fields, initial = {}, onSubmit, onCancel, submitLabel = "Guardar", onDelete }) => {
  const [v, setV] = useState(initial);
  const [err, setErr] = useState({});
  const set = (k, val) => setV((s) => ({ ...s, [k]: val }));
  const submit = () => {
    const e = {};
    fields.forEach((f) => {
      if (f.required && !String(v[f.key] ?? "").trim()) e[f.key] = "Requerido";
      if (f.type === "email" && v[f.key] && !/^\S+@\S+\.\S+$/.test(v[f.key])) e[f.key] = "Email inválido";
    });
    setErr(e);
    if (Object.keys(e).length) return;
    const out = { ...v };
    fields.forEach((f) => { if (f.type === "number") out[f.key] = Number(out[f.key] || 0); });
    onSubmit(out);
  };
  return (
    <>
      <div className="grid sm:grid-cols-2 gap-5">
        {fields.map((f) => (
          <div key={f.key} className={f.full ? "sm:col-span-2" : ""}>
            <Field label={f.label + (f.required ? " *" : "")} error={err[f.key]}>
              {f.type === "select" ? (
                <select value={v[f.key] ?? (typeof f.options[0] === "string" ? f.options[0] : f.options[0].value)}
                        onChange={(e) => set(f.key, e.target.value)} className={inputCls} style={{ ...inputStyle, borderColor: err[f.key] ? "#dc2626" : C.line }}>
                  {f.options.map((o) => (typeof o === "string" ? <option key={o} value={o}>{o}</option> : <option key={o.value} value={o.value}>{o.label}</option>))}
                </select>
              ) : f.type === "textarea" ? (
                <textarea rows={f.rows ?? 3} value={v[f.key] ?? ""} onChange={(e) => set(f.key, e.target.value)} placeholder={f.placeholder}
                          className={inputCls} style={{ ...inputStyle, borderColor: err[f.key] ? "#dc2626" : C.line }} />
              ) : (
                <input type={f.type === "number" ? "number" : f.type === "date" ? "date" : f.type === "time" ? "time" : "text"}
                       value={v[f.key] ?? ""} onChange={(e) => set(f.key, e.target.value)} placeholder={f.placeholder}
                       className={inputCls} style={{ ...inputStyle, borderColor: err[f.key] ? "#dc2626" : C.line }} />
              )}
            </Field>
          </div>
        ))}
      </div>
      <div className="flex items-center justify-between gap-3 mt-8 pt-6 border-t" style={{ borderColor: C.line }}>
        <div>{onDelete && <Btn variant="danger" icon={Trash2} onClick={onDelete}>Eliminar</Btn>}</div>
        <div className="flex gap-3">
          {onCancel && <Btn variant="ghost" onClick={onCancel}>Cancelar</Btn>}
          <Btn variant="accent" icon={Save} onClick={submit}>{submitLabel}</Btn>
        </div>
      </div>
    </>
  );
};

